<script lang="ts">
	import WorkspaceChrome from '$lib/components/WorkspaceChrome.svelte';
	import { resolve } from '$app/paths';
	let { data, form } = $props();
	let showTemporaryPassword = $state(false);
	let showPassword = $state(false);
	let copiedPassword = $state(false);
	const canManage = $derived(['owner', 'admin', 'manager'].includes(data.membership.role));
	$effect(() => {
		if (form?.temporaryPassword) {
			showTemporaryPassword = true;
			copiedPassword = false;
		}
	});
	const closeTemporaryPassword = () => {
		showTemporaryPassword = false;
		copiedPassword = false;
		if (form?.temporaryPassword) form = { ...form, temporaryPassword: undefined };
	};
	const copyTemporaryPassword = async () => {
		if (!form?.temporaryPassword) return;
		try {
			await navigator.clipboard.writeText(form.temporaryPassword);
			copiedPassword = true;
		} catch {
			copiedPassword = false;
		}
	};
	const money = (value: number | string | null | undefined) => new Intl.NumberFormat('en-US', { style: 'currency', currency: data.organization.currency_code }).format(Number(value ?? 0));
	const date = (value: string | null | undefined) => value ? new Intl.DateTimeFormat('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }).format(new Date(value)) : 'Not recorded';
	const dateTime = (value: string | null | undefined) => value ? new Intl.DateTimeFormat('en-GB', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)) : 'Not recorded';
	const label = (value: string | null | undefined) => (value ?? 'Not recorded').replaceAll('_', ' ');
	const activeTenancies = $derived(data.tenancies.filter((item: { status: string }) => ['active', 'ending_soon'].includes(item.status)));
	const totalDue = $derived(data.charges.filter((item: { status: string }) => !['paid', 'void'].includes(item.status)).reduce((sum: number, item: { amount: number }) => sum + Number(item.amount), 0));
	const totalPaid = $derived(data.payments.reduce((sum: number, item: { amount: number }) => sum + Number(item.amount), 0));
	const openMaintenance = $derived(data.maintenance.filter((item: { status: string }) => !['completed', 'closed'].includes(item.status)));
</script>

<svelte:head><title>{data.person.first_name} {data.person.last_name} · Tenant profile · Musha</title></svelte:head>
<WorkspaceChrome organization={data.organization} modules={data.modules} active="people" role={data.membership.role} supportMode={data.supportMode}>
	<a class="back" href={resolve(`/workspace/${data.organization.id}/tenants`)}>← Back to tenant table</a>
	<section class="hero">
		<div class="avatar">{data.person.first_name[0]}{data.person.last_name[0]}</div>
		<div><p class="eyebrow">Tenant 360° profile</p><h1>{data.person.first_name} {data.person.last_name}</h1><p class="hero-meta">{data.person.email ?? 'No email'} · {data.person.phone ?? 'No phone'}</p></div>
		<span class:inactive={!data.person.user_id} class="portal-badge">{data.person.user_id ? 'Portal connected' : 'Portal not connected'}</span>
	</section>

	{#if canManage}<details class="edit-disclosure"><summary>Edit tenant information</summary><form method="POST" action="?/updateTenant" class="edit-form"><div class="form-grid two"><label>First name<input name="first_name" value={data.person.first_name} required /></label><label>Last name<input name="last_name" value={data.person.last_name} required /></label><label>Email<input name="email" type="email" value={data.person.email ?? ''} /></label><label>Phone<input name="phone" value={data.person.phone ?? ''} /></label><label>National ID / reference<input name="id_number" value={data.person.id_number ?? ''} /></label><label>Date of birth<input name="date_of_birth" type="date" value={data.person.date_of_birth ?? ''} /></label><label>Address<input name="address_line_1" value={data.person.address_line_1 ?? ''} /></label><label>City<input name="city" value={data.person.city ?? ''} /></label><label>Country<input name="country" value={data.person.country ?? ''} /></label></div><label>Profile notes<textarea name="notes" rows="3">{data.person.notes ?? ''}</textarea></label><button class="primary" type="submit">Save tenant details <span>→</span></button></form></details>{/if}
	<div class="metric-row">
		<div class="metric-card dark"><span>Active tenancies</span><strong>{activeTenancies.length}</strong><small>{data.tenancies.length} total records</small></div>
		<div class="metric-card"><span>Outstanding charges</span><strong>{money(totalDue)}</strong><small>Open and overdue balances</small></div>
		<div class="metric-card"><span>Paid to date</span><strong>{money(totalPaid)}</strong><small>{data.payments.length} payment records</small></div>
		<div class="metric-card"><span>Open maintenance</span><strong>{openMaintenance.length}</strong><small>Requests raised by tenant</small></div>
	</div>

	{#if canManage}<section class="panel profile-tools"><div class="panel-heading"><div><p class="eyebrow">Profile maintenance</p><h2>Keep tenant records current</h2><p>Manage emergency contacts and identity documents without leaving this profile.</p></div></div><div class="profile-tool-grid"><details class="edit-disclosure"><summary>Add emergency contact</summary><form method="POST" action="?/addEmergencyContact" class="edit-form"><label>Tenancy<select name="tenancy_id" required><option value="">Choose tenancy</option>{#each data.tenancies as tenancy}<option value={tenancy.id}>{tenancy.property?.name ?? 'Property'} · {tenancy.space?.name ?? 'Space'}</option>{/each}</select></label><div class="form-grid two"><label>First name<input name="first_name" required /></label><label>Last name<input name="last_name" required /></label><label>Relationship<input name="relationship" placeholder="Parent, spouse, guardian" /></label><label>Phone<input name="phone" /></label><label>Email<input name="email" type="email" /></label></div><button class="primary" type="submit">Add emergency contact <span>→</span></button></form></details><details class="edit-disclosure"><summary>Update tenant documents</summary><form method="POST" action="?/uploadTenantDocument" enctype="multipart/form-data" class="edit-form"><label>File<input name="file" type="file" accept="application/pdf,image/jpeg,image/png,image/webp" required /></label><div class="form-grid two"><label>Document type<select name="document_type"><option value="id">Identity document</option><option value="lease">Lease agreement</option><option value="notice">Notice</option><option value="other">Other</option></select></label><label>Expires on<input name="expires_on" type="date" /></label></div><label>Attach to tenancy<select name="tenancy_id"><option value="">Tenant record only</option>{#each data.tenancies as tenancy}<option value={tenancy.id}>{tenancy.property?.name ?? 'Property'} · {tenancy.space?.name ?? 'Space'}</option>{/each}</select></label><button class="primary" type="submit">Upload document <span>→</span></button></form>{#if data.documents.length}<div class="managed-document-list">{#each data.documents as document}<div class="managed-document"><div><strong>{document.file_name}</strong><small>{label(document.document_type)} · {date(document.expires_on)}</small></div><form method="POST" action="?/deleteTenantDocument"><input type="hidden" name="document_id" value={document.id} /><button class="text-danger" type="submit">Remove</button></form></div>{/each}</div>{/if}</details></div></section>{/if}
	<div class="profile-grid">
		<section class="panel contact-panel"><div class="panel-heading"><div><p class="eyebrow">Identity & contact</p><h2>Personal details</h2></div></div><dl>
			<div><dt>Email</dt><dd>{data.person.email ?? 'Not recorded'}</dd></div><div><dt>Phone</dt><dd>{data.person.phone ?? 'Not recorded'}</dd></div><div><dt>National ID / reference</dt><dd>{data.person.id_number ?? 'Not recorded'}</dd></div><div><dt>Location</dt><dd>{[data.person.city, data.person.country].filter(Boolean).join(' · ') || 'Not recorded'}</dd></div><div class="wide"><dt>Profile notes</dt><dd>{data.person.notes ?? 'No manager notes recorded.'}</dd></div>
		</dl></section>
		<section class="panel contact-panel"><div class="panel-heading"><div><p class="eyebrow">Safety & communication</p><h2>Emergency contacts</h2><p>People linked to this tenant’s active lease.</p></div></div>{#if data.emergencyContacts.length}<div class="contact-list">{#each data.emergencyContacts as contact}{#if contact.person}<div class="contact-row"><div class="mini-avatar">{contact.person.first_name[0]}{contact.person.last_name[0]}</div><div><strong>{contact.person.first_name} {contact.person.last_name}</strong><small>{contact.person.phone ?? 'No phone'} · {contact.person.email ?? 'No email'}{contact.person.notes ? ` · ${contact.person.notes}` : ''}</small></div><span class="tag">Emergency</span>{#if canManage}<form method="POST" action="?/removeEmergencyContact"><input type="hidden" name="tenancy_id" value={contact.tenancy_id} /><input type="hidden" name="contact_id" value={contact.person_id} /><button class="text-danger" type="submit">Remove</button></form>{/if}</div>{/if}{/each}</div>{:else}<div class="empty compact"><strong>No emergency contact linked.</strong><p>Add an emergency-contact party to a tenancy.</p></div>{/if}</section>
	</div>

	<section class="panel"><div class="panel-heading"><div><p class="eyebrow">Lease register</p><h2>Tenancies, check-in and move-out</h2><p>Every property relationship, term, rent obligation, and occupancy date in one place.</p></div><span class="count">{data.tenancies.length} record{data.tenancies.length === 1 ? '' : 's'}</span></div>{#if data.tenancies.length}<div class="tenancy-list">{#each data.tenancies as tenancy}<article class="tenancy-card"><div class="tenancy-top"><div><strong>{tenancy.property?.name ?? 'Property not found'} · {tenancy.space?.name ?? 'Space not found'}</strong><small>{tenancy.lease_reference ?? 'No lease reference'} · {label(tenancy.status)}</small></div><span class="tag status">{label(tenancy.status)}</span></div><div class="detail-grid"><div><dt>Lease term</dt><dd>{date(tenancy.start_date)} → {date(tenancy.end_date)}</dd></div><div><dt>Check-in</dt><dd>{dateTime(tenancy.move_in_at)}</dd></div><div><dt>Move-out</dt><dd>{dateTime(tenancy.move_out_at)}</dd></div><div><dt>Rent</dt><dd>{money(tenancy.rent_amount)} · {label(tenancy.billing_frequency)}</dd></div><div><dt>Deposit</dt><dd>{money(tenancy.deposit_amount)}</dd></div><div><dt>Due day</dt><dd>{tenancy.rent_due_day ? `Day ${tenancy.rent_due_day} monthly` : 'Not set'}</dd></div></div>{#if tenancy.notes}<p class="note">{tenancy.notes}</p>{/if}</article>{/each}</div>{:else}<div class="empty"><strong>No tenancy linked.</strong><p>Link this tenant to a lease to see occupancy and financial details.</p></div>{/if}</section>

	<div class="profile-grid">
		<section class="panel"><div class="panel-heading"><div><p class="eyebrow">Documents</p><h2>Tenant document register</h2><p>IDs, leases, notices, and supporting documents.</p></div><span class="count">{data.documents.length}</span></div>{#if data.documents.length}<div class="document-list">{#each data.documents as document}<a href={document.url ?? '#'} target="_blank" rel="noreferrer" class="document-row"><span class="file-icon">↗</span><span><strong>{document.file_name}</strong><small>{label(document.document_type)} · {label(document.approval_status)} · Expires {date(document.expires_on)}</small></span></a>{/each}</div>{:else}<div class="empty compact"><strong>No tenant documents yet.</strong><p>Upload identity and lease records from Documents.</p></div>{/if}</section>
		<section class="panel"><div class="panel-heading"><div><p class="eyebrow">Account history</p><h2>Recent payments</h2><p>Manual receipts and payment references linked to this tenant.</p></div></div>{#if data.payments.length}<div class="payment-list">{#each data.payments.slice(0, 6) as payment}<div class="payment-row"><div><strong>{money(payment.amount)}</strong><small>{date(payment.payment_date)} · {label(payment.method)}</small></div><span>{payment.reference ?? 'No reference'}</span></div>{/each}</div>{:else}<div class="empty compact"><strong>No payments recorded.</strong><p>Payments will appear here once recorded against a tenancy.</p></div>{/if}</section>
	</div>

	<section class="panel"><div class="panel-heading"><div><p class="eyebrow">Service history</p><h2>Maintenance requests</h2><p>Issues reported by this tenant and their current resolution state.</p></div></div>{#if data.maintenance.length}<div class="service-table"><div class="service-head"><span>Request</span><span>Location</span><span>Reported</span><span>Status</span></div>{#each data.maintenance as request}<div class="service-row"><div><strong>{request.title}</strong><small>{label(request.category)} · {label(request.priority)}</small></div><span>{request.property_id ? 'Property request' : 'Not linked'}{request.space_id ? ' · Space linked' : ''}</span><span>{date(request.reported_at ?? request.created_at)}</span><span class="tag status">{label(request.status)}</span></div>{/each}</div>{:else}<div class="empty compact"><strong>No maintenance requests from this tenant.</strong><p>New requests will be tracked here with their resolution status.</p></div>{/if}</section>
<section class="panel security-panel"><div class="panel-heading"><div><p class="eyebrow">Portal access</p><h2>Tenant access credentials</h2><p>Create a one-time temporary password for this tenant. Share it securely and ask them to change it after signing in.</p></div><span class:inactive={!data.person.user_id} class="portal-badge">{data.person.user_id ? 'Account linked' : 'Needs account'}</span></div>{#if form?.message}<div class:failure={!form.success} class="notice">{form.message}</div>{/if}<form method="POST" action="?/setTemporaryPassword" class="password-form"><label>Temporary password<span class="field-hint">Minimum 8 characters</span><span class="password-field"><input name="temporary_password" type={showPassword ? 'text' : 'password'} minlength="8" required placeholder="Enter a temporary password" autocomplete="new-password" /><button class="visibility-toggle" type="button" aria-label={showPassword ? 'Hide temporary password' : 'Show temporary password'} onclick={() => (showPassword = !showPassword)}>{showPassword ? 'Hide' : 'Show'}</button></span></label><button class="primary access-button" type="submit">Create temporary access <span>→</span></button></form></section>
	{#if showTemporaryPassword && form?.temporaryPassword}<div class="modal-backdrop" role="presentation" onclick={closeTemporaryPassword}><div class="password-modal" role="dialog" aria-modal="true" aria-labelledby="temporary-password-title" tabindex="-1" onclick={(event) => event.stopPropagation()} onkeydown={(event) => event.stopPropagation()}><button class="modal-close" type="button" aria-label="Close temporary password" onclick={closeTemporaryPassword}>×</button><p class="eyebrow">One-time access</p><h2 id="temporary-password-title">Temporary password ready</h2><p class="modal-copy">Share this password securely with {data.person.first_name}. It will disappear when you close this window.</p><div class="password-reveal"><code>{form.temporaryPassword}</code><button class="copy-button" type="button" onclick={copyTemporaryPassword}>{copiedPassword ? 'Copied' : 'Copy password'}</button></div><button class="primary modal-done" type="button" onclick={closeTemporaryPassword}>Done</button></div></div>{/if}
</WorkspaceChrome>

<style>
